// Original adult residents. Broad comic archetypes, with original identities,
// histories and dialogue. No licensed names, likenesses or catchphrases.
const make=(id,name,fullName,age,room,presentation,skin,hair,hairStyle,body,hobby,title,bio,hello,ambient,topics,extra={})=>({id,name,fullName,age,room,presentation,skin,hair,hairStyle,body,hobby,title,bio,hello,line:hello,ambient,topics:topics.map(([label,keywords,reply])=>({label,keywords:keywords.split('|'),reply})),...extra});
export const RESIDENTS=[
 // Sofia is the hotel's resident con artist; her live conversation runs on dist/sofia.js. These lines feed
 // her profile, ambient bubbles and the residents' own conversations with her.
 make(0,'Sofia','Sofia Delacroix (allegedly)',38,'lobby','woman','#c98d6a','#16100f','long','#a3202f','schemes','The hotel’s most dangerous flirt','Parisian, allegedly, and French when it counts. Has been a duchess, an architect and a jewel appraiser, sometimes in the same evening. Has kissed half the guest list, never pays for a drink, and has her eye on suite 408. And its resident.','Well, well. The new resident of 408. I’ve been dying to get my hands on you. And your room key.', ['Lovely lamp. Lovely legs. Mine, obviously.','I never lie. I flirt with the truth until it gives in.','Somebody in this lobby owes me a kiss. Several somebodies.'],[['Who she really is','who|real|true|name','Darling, I’m whoever the evening requires. Tonight, your problem.'],['Suite 408','408|suite|room|key','Corner suite, city view, very big bed. Wasted on one person.'],['A hotel tip','where|explore|room','The rooftop after dark. Very dark corners. Bring someone. Bring me.']],{look:'fatale'}),
 make(1,'Jules','Jules Mercier',41,'lobby','man','#ecd0ab','#65503e','crop','#7b8ba6','records','The opinionated record collector','An interior stylist with an unreasonable number of records. Can hear a bad speaker from the lift, but secretly loves a terrible pop chorus.','Welcome. I was just wondering who chose this lamp. An interesting decision.', ['That bass line needs a better speaker.','A scratch is character. Usually.','I own the original pressing. Of course.'],[['Your records','record|vinyl|music','One wall of jazz, one wall of soul, and a drawer of pop I deny owning.'],['The room design','design|lamp|decor','Give a room one thing you love, then stop buying things to impress strangers.'],['A guilty pleasure','guilty|pop|secret','A spectacularly silly chorus. Don’t tell Zuri; she’ll put it in her set.']]),
 make(2,'Ada','Ada Okoro',46,'lobby','woman','#6f442f','#25252b','locs','#8d9977','cities','The planner with a pencil','An urban planner who measures every lobby by how comfortable its least confident visitor feels. Keeps sketching better benches on napkins.','Hello. Lovely to meet you. Is that chair comfortable, or merely expensive?', ['A bench should invite a conversation.','This entrance could use a ramp.','I’m sketching. It’s how I listen.'],[['Your sketches','sketch|city|plan','A city is a thousand small invitations. I try to make mine kinder.'],['A better hotel','hotel|design|chair','Some quiet seating, clearer signs, and a place to put a very wet umbrella.'],['Your notebook','note|pencil|book','Mostly buildings. Some excellent sandwiches. Both need thoughtful construction.']]),
 make(3,'Otto','Otto Ward',58,'lobby','man','#d6a080','#9d9b90','crop','#a78d64','repairs','The unofficial repair department','A retired stage carpenter who cannot walk past a wobbly table. His pockets contain three screws, a toffee, and exactly the right tool.','Evening. If something rattles, don’t hit it. Tell me first.', ['That squeak has a name. I’ll find it.','Measure twice. Tea once.','They don’t make hinges like they used to.'],[['What are you fixing?','fix|repair|table','That table isn’t wobbling anymore. Now it’s the floor’s turn to confess.'],['Your theatre days','theatre|stage|job','Built a staircase for a ghost once. Best-behaved actor in the production.'],['A useful tool','tool|screw|pocket','A small screwdriver and the patience to find out what actually broke.']]),
 make(4,'Farah','Farah Aziz',49,'lobby','woman','#a96f48','#353039','bun','#688892','books','The dry-witted night concierge','Knows every shortcut, lost scarf and late-night snack in the building. Collects detective novels and refuses to reveal the endings.','Welcome to The Grand. You look considerably less lost than yesterday’s string quartet.', ['The lift is not a dressing room.','Another scarf. Another mystery.','The culprit is never the houseplant.'],[['A hotel mystery','mystery|detective|book','Someone keeps moving the chess knight. Mabel knows more than she’s saying.'],['A local tip','where|explore|food','The rooftop for a view, Gold Lounge for a quiet chair. Rafi for an unsolicited recipe.'],['Working nights','night|job|work','People tell the truth after midnight. Or invent much better stories.']]),
 make(5,'Inez','Inez Soto',67,'gold','woman','#c28b68','#c9c6bc','bob','#875a6a','debate','The retired lawyer with the last word','Elegant, exacting and warmly formidable. A crossword in one hand and a devastating follow-up question ready in the other.','Good evening. I’ll offer an opinion, but I reserve the right to cross-examine yours.', ['That is not quite what you said before.','A persuasive hat. Weak argument.','I’ve finished the crossword. Naturally.'],[['Your legal career','law|career|argue','Listening did more work than shouting. Though a well-timed silence was excellent too.'],['A difficult crossword','crossword|puzzle','The answer was “equivocate”. A word I heard rather often at work.'],['These cabinets','bet|game|cabinet','A few fictional rounds, then a conversation. I set the limit before I sit down.']],{accessory:'glasses'}),
 make(6,'Rafi','Rafi Costa',35,'gold','man','#b27850','#302c28','curls','#bc845c','cooking','The chef who feeds everyone','A cheerful chef convinced every minor crisis can be improved with food. Carries recipe ideas in the margins of hotel stationery.','Hello! Before anything else: have you eaten something good today?', ['Needs lemon. Most things do.','I’m not judging. I’m seasoning.','Who wants the last pastry?'],[['Your signature dish','cook|food|recipe','Crisp potatoes, smoky peppers, a sharp green sauce. Eat it while it’s still loud.'],['A cooking disaster','disaster|burn|kitchen','I once salted a dessert twice. Called it experimental. Nobody asked for seconds.'],['What’s next?','next|dream|restaurant','A tiny place with six tables, a long lunch, and no one taking photos of the butter.']]),
 make(7,'Mabel','Mabel Reed',72,'gold','woman','#f0d9bd','#dedbd2','bun','#7a8f95','chess','The softly spoken chess shark','Looks like she came for the biscuits. Has already noticed your weak flank and remembers every move you made.','Sit down, dear. We can discuss something harmless. Such as your opening mistakes.', ['A quiet move is still a threat.','That knight was there a moment ago.','Tea first. Checkmate later.'],[['A game of chess','chess|knight|game','Make a plan, watch the other person’s plan, and don’t fall in love with your queen.'],['Your reputation','shark|win|reputation','People find a cardigan reassuring. It’s a very useful opening advantage.'],['The missing knight','missing|mystery|farah','I’m sure it has simply gone for a walk. Knights do that in rather odd patterns.']],{accessory:'glasses'}),
 make(8,'Kofi','Kofi Mensah',52,'gold','man','#66412f','#29282b','crop','#b7985d','theatre','The actor between grand entrances','A theatre actor with a marvellous voice and a fondness for dreadful puns. Rehearses quietly until someone asks him to speak up.','Ah, a new face! Every room is improved by a promising entrance.', ['A pause is also a line.','The velvet here has range.','I was rather good as a tree once.'],[['Your favourite role','role|actor|stage','A king with one scene and a spectacular coat. I made those forty seconds count.'],['An acting lesson','act|lesson|voice','Know what you want from the person in front of you. Then actually listen to them.'],['A terrible joke','joke|pun|laugh','I left the mime company. We weren’t speaking. I warned you it was dreadful.']]),
 make(9,'Esme','Esme Laurent',63,'gold','woman','#dfb28e','#b7b4ad','bob','#679a91','dance','The dancer with an excellent eye','A former ballet dancer who now teaches people to enjoy moving. Fiercely dislikes anyone calling a body the wrong shape.','Good evening. Shoulders down. Nobody needs to audition for the lobby.', ['A little balance, a little breath.','Those shoes tell a whole story.','There is no wrong body for dancing.'],[['Learning to dance','dance|learn|ballet','Start with a song you can’t sit still to. Technique can catch up with joy.'],['A life on stage','stage|past|career','Wonderful friendships. Uncomfortable shoes. I kept the friendships.'],['Style advice','style|clothes|wear','Wear the thing that lets you stand like yourself. Confidence fits better than a label.']]),
 make(10,'Kit','Kit Rook',27,'neon','man','#cf9b74','#784d33','messy','#c9805b','skate','The charming rule-bender','A skateboard courier with a quick grin and questionable respect for “staff only” signs. His pranks are elaborate, harmless, and usually discovered by Farah.','Hey. If anyone asks, the tiny skateboard in the lift was an art installation.', ['That rail is asking a question.','No, I did not move the bell.','The sign said no running. I rolled.'],[['Your skateboard','skate|board|trick','I’m practising a clean kickflip. Quiet wheels, no tricks near people, and absolutely no broken lamps.'],['Your latest prank','prank|naughty|trouble','I replaced every “reserved” card with “emotionally unavailable”. Farah found me in six minutes.'],['Your day job','job|courier|work','Fast deliveries and a good mental map. The lift is cheating, but the parcels don’t complain.']],{accessory:'skateboard'}),
 make(11,'Bea','Bea Chen',29,'neon','woman','#e0b68e','#242a32','bob','#8588b5','stars','The astronomer after hours','An astronomer who likes enormous questions and very small mechanical toys. Will happily explain a planet using three coasters and your drink.','Hi. Do these cabinets remind you of a slightly overexcited observatory?', ['That’s a surprisingly good star map.','Space is bigger than your calendar.','I brought a pocket telescope.'],[['A favourite planet','planet|space|star','Saturn. I’m allowed an obvious favourite; it wears its argument rather well.'],['The little toys','toy|mechanical|collect','Tiny wind-up robots. Something about a determined little machine makes me happy.'],['Tonight’s sky','sky|roof|tonight','Let’s go upstairs after the lights dim. Half the fun is looking with someone else.']]),
 make(12,'Wren','Wren Park',26,'neon','neutral','#a97452','#252930','crop','#668c83','magic','The magician with terrible timing','A close-up magician who can make a coin vanish but always loses their room key by ordinary means. Delights in making sceptics smile.','Pick a card. Or don’t. I’m trying to become less controlling about the whole thing.', ['It was in your pocket. Possibly.','Now where did I put my actual key?','The secret is mostly practice.'],[['A magic trick','magic|trick|card','Watch the hand doing absolutely nothing interesting. Yes, that one.'],['Losing your key','key|lost|room','Professional misdirection. Unfortunately I also misdirect myself.'],['Learning magic','learn|practice|secret','One simple trick, practised until you can talk normally while doing it. That’s the hard part.']],{hat:'beret'}),
 make(13,'Niko','Niko Voss',28,'neon','man','#efc7a3','#3a3430','crop','#7d91ad','games','The enthusiast with the rulebook','A board-game organiser who loves precise rules and unexpected strategies. Competitive for twenty minutes, generous with snacks forever.','Hello. I have a game that takes twelve minutes to explain. We can probably do ten.', ['That rule is actually in the appendix.','A draw can be an elegant result.','Who has the instruction leaflet?'],[['Your game nights','game|board|night','Everyone gets a turn, nobody gets eliminated early, and somebody brings a ridiculous game.'],['Being competitive','win|compete|lose','I enjoy a good opponent more than an easy win. Please quote me if I forget that.'],['The cabinets','bet|slot|cabinet','The outcomes are random. My notebook is for board-game scores, not predicting a reel.']]),
 make(14,'Dev','Dev Malik',36,'neon','man','#8d5b3c','#302b2a','curls','#a47c91','puzzles','The cryptic clue collector','A software designer who constructs crosswords on trains. Hears wordplay everywhere, especially when someone is trying to have a serious conversation.','Pleased to meet you. “Hotel resident, initially rather grand”: five letters. Never mind, still drafting.', ['That clue needs a better surface.','An anagram is a very small holiday.','Inez got it in four seconds.'],[['A cryptic clue','clue|puzzle|crossword','“Listen differently for quiet”: SILENT. I like a word that quietly becomes its own answer.'],['Your design work','design|software|job','I make complicated things a little easier to use. Then I make my crosswords harder. Balance.'],['Your rival','rival|inez|mabel','Inez solves them in pen. That is either confidence or a very specific form of aggression.']],{accessory:'glasses'}),
 make(15,'Noor','Noor Vale',32,'roof','woman','#855737','#29262b','curls','#aa7183','sax','The saxophonist with a reading list','A jazz saxophonist and community archivist. Loves a winding melody, a sharp debate, and the women who changed history without waiting to be invited.','Hello. I’m choosing between a late set and a book about remarkable women. Happily, there’s time for both.', ['A melody needs somewhere to breathe.','Josephine Baker is on my reading list.','Strong women, strong coffee, good music.'],[['Your saxophone','sax|jazz|music','I like a melody that wanders and still finds its way home. Want to hear a little phrase?'],['Women in history','women|history|baker|chisholm|hopper','Josephine Baker, Shirley Chisholm, Grace Hopper. Three very different shelves in my ever-growing reading list.'],['Your archive','archive|community|book','The ordinary voices matter too. I record stories before somebody decides they weren’t important.']],{accessory:'sax-pin'}),
 make(16,'Zuri','Zuri Dube',34,'roof','woman','#68422e','#23232a','afro','#c29a62','dj','The DJ who reads the room','A DJ with an encyclopaedic ear and a patient smile. Can turn a shy gathering into a dance floor without raising the volume.','Evening. Tell me one song you love. I’ll try to find its most interesting neighbour.', ['The next track needs a little space.','Jules secretly likes this chorus.','A dance floor is a conversation.'],[['Your next set','dj|set|music|song','A little soul, a left turn into house, then something your aunt knows every word to.'],['Reading the room','room|crowd|dance','Watch who’s tapping a finger before you look for anyone dancing. The quiet people tell you plenty.'],['Jules’s secret','jules|secret|pop','He knows the entire chorus. He just sings it with a very serious expression.']],{accessory:'headphones'}),
 make(17,'Arun','Arun Shah',44,'roof','man','#a76f47','#393231','locs','#7b9473','plants','The botanist who brought cuttings','A botanist taking a proper holiday, according to everyone except the plants. Travels with a pocket lens and far too many labelled envelopes.','Hello there. The view is excellent. That palm could use a little less water.', ['A new leaf is a very good review.','No, it isn’t dead. It’s resting.','Sofia understands a dramatic stem.'],[['Your plants','plant|palm|garden','Start with the light you actually have. A plant cannot live on your ambition.'],['Your envelopes','envelope|seed|travel','Seeds, cuttings, labels. Customs officers have heard my entire life story.'],['A proper holiday','holiday|work|rest','I am resting. I merely happen to be resting beside a fascinating leaf.']]),
 make(18,'Luca','Luca Bell',31,'roof','man','#bd8963','#41322c','messy','#8f8dba','fashion','The tailor with a generous eye','A tailor who notices a beautiful seam before a famous label. Helps friends find a look that belongs to them, then fixes the pockets.','Hi. That outfit has possibilities. Do the pockets work? That’s my first question.', ['A jacket needs proper pockets.','Good colour. Very good colour.','The boutique’s beret is tempting.'],[['A personal style','style|fashion|jacket','Find your colours, let your clothes move, and insist on pockets. You are a person, not a mannequin.'],['The boutique','store|shop|boutique|buy','I like the cobalt jacket and the beret. Try them on first; a price tag is not a personality.'],['Your tailoring','tailor|seam|job','Small adjustments can make a thing feel entirely yours. Hemlines, sleeves, confidence.']],{hat:'fedora'}),
 make(19,'Tessa','Tessa Quinn',39,'roof','woman','#e8bc98','#9b6647','long','#6e97a7','stories','The journalist off the record','A curious journalist who promised not to work this weekend. Asks excellent questions, respects a closed notebook, and tells surprisingly good stories herself.','Hello. No interview, I promise. Unless you have a genuinely excellent story about a hat.', ['Off the record means off the record.','That’s a much better question.','Farah has the best stories here.'],[['A memorable story','story|journalist|job','A small community saved its library with a very stubborn book club. I still get their reading list.'],['Asking questions','question|interview|listen','Ask what someone wishes people understood. Then leave enough silence for the answer.'],['Your weekend','weekend|holiday|work','No deadlines. A rooftop, a conversation, and absolutely no checking my inbox.']])
];

// Hotel staff (spec §3.1): functional NPCs. They are not residents: they stay at their post, never travel,
// gamble or join residents' conversations, and don't count towards "residents met". Their live conversation
// runs on a persona in dist/personas/. Ids start at 100 so they never collide with residents.
export const STAFF=[
 make(100,'Mr Penrose','Mr Ambrose Penrose',61,'hall','man','#e2bf9f','#c3c3bd','crop','#2f3b4a','terms','Clerk of Small Print','Keeps the hotel’s terms at a desk in the Gallery. Reads every clause exactly as written and will not guess how one applies to you.','Penrose, Clerk of Small Print. Which clause can I find for you?',['Every word in its place.','The clause itself is the one that counts.','Version 0.3, and proud of it.'],[['The terms','terms|clause|rule','Ask me about any clause and I’ll show you the wording.']],{staff:true,post:'At the small-print desk',desk:[5,1]}),
 make(101,'Celeste','Celeste Marchand',34,'lobby','woman','#9a6445','#1d1513','bun','#6e2f3f','bonuses','The Bonus Concierge','Runs the concierge desk in the lobby. Knows every offer the hotel runs and the terms that come with each, and will not tell you which one to pick.','Good evening. How can I help?',['The desk is open all evening.','Every offer comes with its terms. Always.','Ask me anything about the bonuses.'],[['The bonuses','bonus|offer|claim','Ask me what’s open to you, or how one works.']],{staff:true,post:'At the concierge desk',desk:[1,0]}),
 make(102,'Pip','Pip Okafor',27,'neon','neutral','#7a4a32','#e86fb0','curls','#3d3a7a','spins','The Spin Attendant','Looks after the Neon Arcade’s cabinets and the free spins that go with them. Knows which games each set is for, and the terms that come with them.','Hey. How can I help?',['The cabinets are all yours.','Every set of spins comes with its terms.','Ask me which games your spins are for.'],[['Free spins','spin|free|game','Ask me what you’ve got, or which games they’re for.']],{staff:true,post:'By the cabinets',desk:[2,1]}),
];
export const isStaff=id=>STAFF.some(s=>s.id===Number(id));
// A resident or a member of staff, by id.
export const personById=id=>RESIDENTS.find(r=>r.id===Number(id))||STAFF.find(s=>s.id===Number(id));

export function residentReply(resident,message,{name='Alex',familiar=false}={},topicIndex=null){
 const text=String(message).toLowerCase();
 const topic=Number.isInteger(topicIndex)?resident.topics[topicIndex]:resident.topics.find(t=>t.keywords.some(k=>text.includes(k)));
 if(topic)return topic.reply;
 if(/hello|hi\b|evening|hey|welcome/.test(text))return `${familiar?`Good to see you again, ${name}.`:`Hello, ${name}. Welcome to The Grand.`} ${resident.hello.replace(/^(Hello(?: there)?|Hi|Hey|Good evening|Evening|Welcome(?: to The Grand)?)[.!,:]?\s*/,'')}`;
 if(/how are|doing|up to/.test(text))return resident.ambient[1];
 return `${resident.ambient[0]} ${resident.topics[0].reply}`;
}
